#!/usr/bin/env bash
# dsba3 shard runner: usage run_shard.sh <gpu_index 0-3>. Runs MVTec and VisA component ablation on one GPU.
set -euo pipefail
G="${1:?gpu index}"
case "$G" in
  0) UUID=GPU-a164a77e-c3b3-5c6d-d70c-63ee65b2601f; MVTEC_OBJ=(bottle grid pill transistor); VISA_OBJ=(candle fryum pcb2) ;;
  1) UUID=GPU-bbb3a0e2-cc7d-ba3c-f956-89214c06a1ae; MVTEC_OBJ=(cable hazelnut screw wood); VISA_OBJ=(capsules macaroni1 pcb3) ;;
  2) UUID=GPU-eb6182a8-eb72-e8b2-f279-c587d6fa9639; MVTEC_OBJ=(capsule leather tile zipper); VISA_OBJ=(cashew macaroni2 pcb4) ;;
  3) UUID=GPU-7534790f-7c8c-3f2b-5c33-c1b15998ef62; MVTEC_OBJ=(carpet metal_nut toothbrush); VISA_OBJ=(chewinggum pcb1 pipe_fryum) ;;
  *) echo bad gpu; exit 2 ;;
esac
MVTEC_CFG=(configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_nonorm_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_deeponly_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_layermean_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_concat_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_nonorm_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_deeponly_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_layermean_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_concat_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_nonorm_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_deeponly_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_layermean_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_concat_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_nonorm_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_deeponly_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_layermean_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_concat_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_nonorm_s16_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_deeponly_s16_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_layermean_s16_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/mvtec_concat_s16_seed0.yaml)
MVTEC_LBL=(mvtec_nonorm_s01_seed0 mvtec_deeponly_s01_seed0 mvtec_layermean_s01_seed0 mvtec_concat_s01_seed0 mvtec_nonorm_s02_seed0 mvtec_deeponly_s02_seed0 mvtec_layermean_s02_seed0 mvtec_concat_s02_seed0 mvtec_nonorm_s04_seed0 mvtec_deeponly_s04_seed0 mvtec_layermean_s04_seed0 mvtec_concat_s04_seed0 mvtec_nonorm_s08_seed0 mvtec_deeponly_s08_seed0 mvtec_layermean_s08_seed0 mvtec_concat_s08_seed0 mvtec_nonorm_s16_seed0 mvtec_deeponly_s16_seed0 mvtec_layermean_s16_seed0 mvtec_concat_s16_seed0)
VISA_CFG=(configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_nonorm_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_deeponly_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_layermean_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_concat_s01_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_nonorm_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_deeponly_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_layermean_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_concat_s02_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_nonorm_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_deeponly_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_layermean_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_concat_s04_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_nonorm_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_deeponly_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_layermean_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_concat_s08_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_nonorm_s16_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_deeponly_s16_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_layermean_s16_seed0.yaml configs/benchmarks/scarf_component_ablation_local_seed0_fp16_20261009/visa_concat_s16_seed0.yaml)
