export PYTHONPATH=$PWD/src PYTHONNOUSERSITE=1 PYTHONUNBUFFERED=1 PYTHONDONTWRITEBYTECODE=1 OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 FMAD_DINOV2_OFFLINE=1
export CUDA_VISIBLE_DEVICES="$UUID"
OUT=/results/scarf_component_ablation_local_seed0_fp16_20261009
mkdir -p "$OUT"
for ds in mvtec visa; do
  if [ "$ds" = mvtec ]; then OBJ=("${MVTEC_OBJ[@]}"); CFG=("${MVTEC_CFG[@]}"); LBL=("${MVTEC_LBL[@]}"); ROOT=/home/hunim/Volume/DATA/MVTecAD;
  else OBJ=("${VISA_OBJ[@]}"); CFG=("${VISA_CFG[@]}"); LBL=("${VISA_LBL[@]}"); ROOT=/home/hunim/Volume/DATA/VisA_pytorch/1cls; fi
  python3 scripts/experiments.py run --configs "${CFG[@]}" --labels "${LBL[@]}" --objects "${OBJ[@]}" --data-root "$ROOT" --output-dir "$OUT/gpu${G}_$ds" --device cuda:0 --timeout 10800 --workers 1 --split "${ds}_seen_development_seed0_component_ablation_local_fp16"
done
